const NL = String.fromCharCode(10);
const w = $json.workflow || {};
const ex = $json.execution || {};
const tr = $json.trigger || {};
const err = ex.error || tr.error || {};
let node = err.node;
if (node && typeof node === "object") { node = node.name || node.type || ""; }
if (!node) { node = ex.lastNodeExecuted || tr.mode || "n/a"; }
const id = (ex.id !== undefined) ? ex.id : (err.timestamp ? "activation" : "n/a");
const lines = [
  "Workflow: " + (w.name || "unknown") + "  [" + (w.id || "") + "]",
  "Node: " + node,
  "Error: " + (err.message || err.description || "n/a"),
  "Exec id: " + id + "   mode: " + (ex.mode || tr.mode || "n/a"),
  "Open: http://127.0.0.1:5678/workflow/" + (w.id || "")
];
return [{ json: { message: lines.join(NL) } }];
